public type Money conforms Display {
    def Display::display.() -> String = { return self.format() }
}

common type Money conforms Display as moneyDisplay via MoneyDisplayProvider {
    def Display::display.() -> String = { return self.format() }
}

public trait Display
supports auto {
    +def display.() -> String throws Never effects {}
}
public type Receipt conforms Display by auto

public trait AutoReceiptIdentity
supports auto {
    +def identity.() -> String throws Never effects {}
}
public class Receipt
derives Document
conforms Display
conforms AutoReceiptIdentity by auto {
    conform Display {
        def display.() -> String = { return self.title }
    }
}

public trait OrderedDisplay
derives Display
derives Ord<Self> {
    +def summary.() -> String throws Never effects {}
}

public value class Meters(value: Rational)
conforms Display {
    conform Display { def display.() -> String = { return "${self.value} m" } }
}

public resource class FileHandle
conforms CleanupAware {
    conform CleanupAware { +def close*+() -> Unit = {} }
}

public trait AutoEnumIdentity
supports auto {
    +def identity.() -> String throws Never effects {}
}
public enum Priority
conforms Display
conforms AutoEnumIdentity by auto {
    low
    high
    conform Display { +def display.() -> String = { return self.name } }
}

public class Box<T>
conforms Display where T conforms Display
conforms Eq<Box<T>> where T conforms Eq<T> {
}

public trait StorageModel {
    type Key
    let ::empty: Key
    def ::make() -> Key
}
public type FileStore conforms StorageModel {
    type Key = Token
    let ::empty = Token::empty
    def ::make() -> Token = { return Token::empty }
}
let key: <FileStore as StorageModel>::Key = <FileStore as StorageModel>::empty

public trait MarkerSet {
    +def borrowed.() -> Unit
    +def static+() -> Unit
    +def consuming*.() -> Unit
    +def consumingStatic*+() -> Unit
}
public type Token conforms MarkerSet {
    def MarkerSet::borrowed.() -> Unit = {}
    def MarkerSet::static+() -> Unit = {}
    def MarkerSet::consuming*.() -> Unit = {}
    def MarkerSet::consumingStatic*+() -> Unit = {}
}

public class Receipt
conforms Display {
    conform Display { def Display::display.() -> String = { return self.title } }
}

public class Child
derives BaseA
derives BaseB { }
